INSERT INTO homework_assignments (id, school_id, class_id, subject_id, teacher_id, title, description, assigned_at, deadline_at, max_score, is_active) VALUES
  ('c8000000-0000-4000-8000-000000000001', 'cc021f70-256f-45c0-be19-ab7beddab1b3', '1bc5be58-cdfd-4a41-a150-b8f3a1cc0e39', 'c5000000-0000-4000-8000-000000000001', 'c6000000-0000-4000-8000-000000000001', 'Diktant: «Kuz»', 'Matnni diqqat bilan eshitib yozing, so''ng tinish belgilarini tekshiring.', now() - interval '3 days', now() + interval '-1 days', 100, true),
  ('c8000000-0000-4000-8000-000000000002', 'cc021f70-256f-45c0-be19-ab7beddab1b3', '1bc5be58-cdfd-4a41-a150-b8f3a1cc0e39', 'c5000000-0000-4000-8000-000000000001', 'c6000000-0000-4000-8000-000000000001', 'Insho: «Mening oilam»', 'Oilangiz haqida 8-10 gapdan iborat insho yozing.', now() - interval '14 days', now() + interval '-9 days', 100, true),
  ('c8000000-0000-4000-8000-000000000003', 'cc021f70-256f-45c0-be19-ab7beddab1b3', 'a3000000-0000-4000-8000-000000000001', 'c5000000-0000-4000-8000-000000000002', 'c6000000-0000-4000-8000-000000000002', 'Present Simple: 10 ta gap', 'Write 10 sentences about your daily routine using Present Simple.', now() - interval '2 days', now() + interval '1 days', 100, true),
  ('c8000000-0000-4000-8000-000000000004', 'cc021f70-256f-45c0-be19-ab7beddab1b3', '1bc5be58-cdfd-4a41-a150-b8f3a1cc0e39', 'c5000000-0000-4000-8000-000000000003', 'c6000000-0000-4000-8000-000000000003', 'Amir Temur davlati', 'Savollarga to''liq javob bering: davlat qachon tuzilgan, poytaxti, asosiy islohotlar.', now() - interval '4 days', now() + interval '-1 days', 100, true)
INSERT INTO homework_submissions (id, school_id, assignment_id, student_id, type, text_content, status, is_late, submitted_at, xp_earned) VALUES
  ('c9000000-0000-4000-8000-000000000001', 'cc021f70-256f-45c0-be19-ab7beddab1b3', 'c8000000-0000-4000-8000-000000000001', 'f2245ba6-6ee5-4161-bcc5-c22ac742459f', 'TEXT', 'Kuz keldi. Daraxtlar sarg''aydi, barglar to''kila boshladi. Biz kecha maktapda kuz bayramini o''tkazdik. Bolalar she''r o''qishdi qo''shiq aytishdi.', 'AI_DONE', false, now() - interval '30 hours', 0),
  ('c9000000-0000-4000-8000-000000000002', 'cc021f70-256f-45c0-be19-ab7beddab1b3', 'c8000000-0000-4000-8000-000000000001', '0969224c-1348-4d49-91c3-034dcea56490', 'TEXT', 'Kuz keldi. Daraxtlar sarg''aydi, barglar to''kila boshladi. Biz kecha maktabda kuz bayramini o''tkazdik. Bolalar she''r o''qishdi, qo''shiq aytishdi.', 'AI_DONE', false, now() - interval '28 hours', 0),
  ('c9000000-0000-4000-8000-000000000003', 'cc021f70-256f-45c0-be19-ab7beddab1b3', 'c8000000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000001', 'TEXT', 'Kuz keldi. Daraxtlar sargʻaydi, barglar tokila boshladi. Biz kecha maktabda kuz bayramni o''tkazdik. Bolalar she''r o''qishdi, qo''shiq aytishdi.', 'AI_DONE', false, now() - interval '26 hours', 0),
  ('c9000000-0000-4000-8000-000000000004', 'cc021f70-256f-45c0-be19-ab7beddab1b3', 'c8000000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000002', 'TEXT', 'Kuz fasli kirib keldi. Daraxtlarning barglari oltin rangga burkanib, mayin shamolda ohista to''kilmoqda. Kecha maktabimizda an''anaviy kuz bayrami bo''lib o''tdi, o''quvchilar she''rlar o''qib, qo''shiqlar ijro etishdi.', 'AI_DONE', false, now() - interval '20 hours', 0),
  ('c9000000-0000-4000-8000-000000000005', 'cc021f70-256f-45c0-be19-ab7beddab1b3', 'c8000000-0000-4000-8000-000000000001', 'a1000000-0000-4000-8000-000000000003', 'TEXT', 'Kuz keldi. daraxtlar sarg''aydi, barglar to''kila boshladi. Biz kecha maktabda kuz bayramini o''tkazdik. Bolalar she''r o''qishdi, qo''shiq aytishdi.', 'AI_DONE', false, now() - interval '18 hours', 0),
  ('c9000000-0000-4000-8000-000000000006', 'cc021f70-256f-45c0-be19-ab7beddab1b3', 'c8000000-0000-4000-8000-000000000002', 'f2245ba6-6ee5-4161-bcc5-c22ac742459f', 'TEXT', 'Mening oilam katta va ahil. Dadam muhandis, oyim o''qituvchi. Akam Jasur bilan bir maktabda o''qiymiz. Dam olish kunlari buvimnikiga boramiz...', 'GRADED', false, now() - interval '300 hours', 35),
  ('c9000000-0000-4000-8000-000000000007', 'cc021f70-256f-45c0-be19-ab7beddab1b3', 'c8000000-0000-4000-8000-000000000002', 'a1000000-0000-4000-8000-000000000001', 'TEXT', 'Bizning oilamiz besh kishidan iborat. Har kuni kechqurun birga choy ichamiz...', 'GRADED', false, now() - interval '290 hours', 35),
  ('c9000000-0000-4000-8000-000000000008', 'cc021f70-256f-45c0-be19-ab7beddab1b3', 'c8000000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000004', 'TEXT', 'I wake up at 7 o''clock. I brush my teeth. My sister go to school with me. We has lunch at 1 pm. I do my homework in the evening.', 'AI_DONE', false, now() - interval '20 hours', 0),
  ('c9000000-0000-4000-8000-000000000009', 'cc021f70-256f-45c0-be19-ab7beddab1b3', 'c8000000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000005', 'TEXT', 'Every day I get up early. I go to school by bus. My mother cooks breakfast. My father works in a bank. I read books before sleep.', 'AI_DONE', false, now() - interval '16 hours', 0),
  ('c9000000-0000-4000-8000-000000000010', 'cc021f70-256f-45c0-be19-ab7beddab1b3', 'c8000000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000006', 'TEXT', 'I usually wakes up at 6:30. Then I does exercises. My brother play football every weekend.', 'AI_DONE', false, now() - interval '12 hours', 0),
  ('c9000000-0000-4000-8000-000000000011', 'cc021f70-256f-45c0-be19-ab7beddab1b3', 'c8000000-0000-4000-8000-000000000003', 'a1000000-0000-4000-8000-000000000007', 'TEXT', 'Every day I get up early. I go to school by bus. My mother cooks breakfast. My father works in a bank. I read books before sleep.', 'AI_DONE', false, now() - interval '10 hours', 0),
  ('c9000000-0000-4000-8000-000000000012', 'cc021f70-256f-45c0-be19-ab7beddab1b3', 'c8000000-0000-4000-8000-000000000004', 'f2245ba6-6ee5-4161-bcc5-c22ac742459f', 'TEXT', 'Amir Temur 1370-yilda hokimiyatga keldi. Davlat poytaxti Samarqand edi. U qurilishga katta e''tibor berdi, Samarqandda Bibixonim masjidi qurildi. Temur tuzuklari davlat qonunlari to''plami edi.', 'AI_DONE', false, now() - interval '40 hours', 0),
  ('c9000000-0000-4000-8000-000000000013', 'cc021f70-256f-45c0-be19-ab7beddab1b3', 'c8000000-0000-4000-8000-000000000004', '0969224c-1348-4d49-91c3-034dcea56490', 'TEXT', 'Amir Temur davlati 1370-yil tuzilgan. Poytaxti Buxoro edi. U ko''p jang qildi.', 'AI_DONE', false, now() - interval '36 hours', 0),
  ('c9000000-0000-4000-8000-000000000014', 'cc021f70-256f-45c0-be19-ab7beddab1b3', 'c8000000-0000-4000-8000-000000000004', 'a1000000-0000-4000-8000-000000000003', 'TEXT', 'Sohibqiron Amir Temur 1370-yilda Balxda qurultoyda oliy hukmdor etib saylandi. Uning davlati poytaxti Samarqand bo''lib, u yerda Ko''ksaroy qasri, Bibixonim jome masjidi bunyod etildi. «Temur tuzuklari»da davlatni boshqarish qoidalari bayon qilingan.', 'AI_DONE', false, now() - interval '30 hours', 0),
  ('c9000000-0000-4000-8000-000000000015', 'cc021f70-256f-45c0-be19-ab7beddab1b3', 'c8000000-0000-4000-8000-000000000004', 'a1000000-0000-4000-8000-000000000002', 'TEXT', 'Amir Temur 1336-yilda Keshda tug''ilgan. Davlat poytaxti Samarqand. U savdo yo''llarini himoya qildi.', 'AI_SKIPPED', false, now() - interval '22 hours', 0)
INSERT INTO ai_feedbacks (id, submission_id, extracted_text, ocr_confidence, step_analyses, criteria_scores, ai_score_percent, feedback, plagiarism_score, plagiarism_type, processed_at) VALUES
  ('ca000000-0000-4000-8000-000000000001', 'c9000000-0000-4000-8000-000000000001', 'Kuz keldi. Daraxtlar sarg''aydi, barglar to''kila boshladi. Biz kecha maktapda kuz bayramini o''tkazdik. Bolalar she''r o''qishdi qo''shiq aytishdi.', 0.93, '[{"stepNumber": 1, "stepContent": "maktapda", "isCorrect": false, "errorDescription": "Imlo: jarangli «b» undoshi yoziladi", "suggestion": "maktabda"}, {"stepNumber": 2, "stepContent": "she''r o''qishdi qo''shiq", "isCorrect": false, "errorDescription": "Tinish belgisi: uyushiq kesimlar orasiga vergul qo''yiladi", "suggestion": "she''r o''qishdi, qo''shiq"}]'::jsonb, '[{"name": "Imlo", "weightPercent": 35, "score": 84}, {"name": "Grammatika va tinish belgilari", "weightPercent": 35, "score": 80}, {"name": "Mazmun va so''z boyligi", "weightPercent": 30, "score": 92}]'::jsonb, 85.0, 'Diktant yaxshi yozilgan. Ikkita xato bor: «maktabda» so''zining imlosi va uyushiq kesimlar orasidagi vergul.', 3.0, 'CLEAN', now() - interval '30 hours' + interval '2 minutes'),
  ('ca000000-0000-4000-8000-000000000002', 'c9000000-0000-4000-8000-000000000002', 'Kuz keldi. Daraxtlar sarg''aydi, barglar to''kila boshladi. Biz kecha maktabda kuz bayramini o''tkazdik. Bolalar she''r o''qishdi, qo''shiq aytishdi.', 0.93, '[]'::jsonb, '[{"name": "Imlo", "weightPercent": 35, "score": 100}, {"name": "Grammatika va tinish belgilari", "weightPercent": 35, "score": 96}, {"name": "Mazmun va so''z boyligi", "weightPercent": 30, "score": 95}]'::jsonb, 97.1, 'Xatosiz diktant. Tinish belgilari ham to''g''ri qo''yilgan.', 2.0, 'CLEAN', now() - interval '28 hours' + interval '2 minutes'),
  ('ca000000-0000-4000-8000-000000000003', 'c9000000-0000-4000-8000-000000000003', 'Kuz keldi. Daraxtlar sargʻaydi, barglar tokila boshladi. Biz kecha maktabda kuz bayramni o''tkazdik. Bolalar she''r o''qishdi, qo''shiq aytishdi.', 0.93, '[{"stepNumber": 1, "stepContent": "tokila", "isCorrect": false, "errorDescription": "Imlo: tutuq belgisi tushib qolgan", "suggestion": "to''kila"}, {"stepNumber": 2, "stepContent": "bayramni", "isCorrect": false, "errorDescription": "Imlo: so''zning o''zagi buzilgan", "suggestion": "bayramini"}]'::jsonb, '[{"name": "Imlo", "weightPercent": 35, "score": 72}, {"name": "Grammatika va tinish belgilari", "weightPercent": 35, "score": 85}, {"name": "Mazmun va so''z boyligi", "weightPercent": 30, "score": 88}]'::jsonb, 81.3, 'Ikkita imlo xatosi bor. Tutuq belgisi va so''z o''zagiga e''tibor bering.', 4.0, 'CLEAN', now() - interval '26 hours' + interval '2 minutes'),
  ('ca000000-0000-4000-8000-000000000004', 'c9000000-0000-4000-8000-000000000004', 'Kuz fasli kirib keldi. Daraxtlarning barglari oltin rangga burkanib, mayin shamolda ohista to''kilmoqda. Kecha maktabimizda an''anaviy kuz bayrami bo''lib o''tdi, o''quvchilar she''rlar o''qib, qo''shiqlar ijro etishdi.', 0.93, '[{"stepNumber": 1, "stepContent": "Matn diktant matniga mos emas", "isCorrect": false, "errorDescription": "Diktant matni o''rniga boshqa, tayyor matn yozilgan", "suggestion": "Diktant matnini o''qituvchi aytganidek yozish kerak"}]'::jsonb, '[{"name": "Imlo", "weightPercent": 35, "score": 95}, {"name": "Grammatika va tinish belgilari", "weightPercent": 35, "score": 95}, {"name": "Mazmun va so''z boyligi", "weightPercent": 30, "score": 60}]'::jsonb, 84.5, 'Matn savodli, lekin diktant matniga mos kelmaydi. Uslubi o''quvchi yozuviga o''xshamaydi.', 81.0, 'AI_GENERATED', now() - interval '20 hours' + interval '2 minutes'),
  ('ca000000-0000-4000-8000-000000000005', 'c9000000-0000-4000-8000-000000000005', 'Kuz keldi. daraxtlar sarg''aydi, barglar to''kila boshladi. Biz kecha maktabda kuz bayramini o''tkazdik. Bolalar she''r o''qishdi, qo''shiq aytishdi.', 0.93, '[{"stepNumber": 1, "stepContent": "daraxtlar", "isCorrect": false, "errorDescription": "Gap bosh harf bilan boshlanadi", "suggestion": "Daraxtlar"}]'::jsonb, '[{"name": "Imlo", "weightPercent": 35, "score": 94}, {"name": "Grammatika va tinish belgilari", "weightPercent": 35, "score": 90}, {"name": "Mazmun va so''z boyligi", "weightPercent": 30, "score": 93}]'::jsonb, 92.3, 'Juda yaxshi. Faqat ikkinchi gap kichik harf bilan boshlangan.', 3.0, 'CLEAN', now() - interval '18 hours' + interval '2 minutes'),
  ('ca000000-0000-4000-8000-000000000006', 'c9000000-0000-4000-8000-000000000006', 'Mening oilam katta va ahil. Dadam muhandis, oyim o''qituvchi. Akam Jasur bilan bir maktabda o''qiymiz. Dam olish kunlari buvimnikiga boramiz...', 0.93, '[{"stepNumber": 1, "stepContent": "oilamiz ahil va katta", "isCorrect": true, "errorDescription": null, "suggestion": null}]'::jsonb, '[{"name": "Imlo", "weightPercent": 35, "score": 90}, {"name": "Grammatika va tinish belgilari", "weightPercent": 35, "score": 85}, {"name": "Mazmun va so''z boyligi", "weightPercent": 30, "score": 88}]'::jsonb, 87.7, 'Insho mazmunli, gaplar to''g''ri tuzilgan.', 4.0, 'CLEAN', now() - interval '300 hours' + interval '2 minutes'),
  ('ca000000-0000-4000-8000-000000000007', 'c9000000-0000-4000-8000-000000000007', 'Bizning oilamiz besh kishidan iborat. Har kuni kechqurun birga choy ichamiz...', 0.93, '[{"stepNumber": 1, "stepContent": "besh kishidan iborat", "isCorrect": true, "errorDescription": null, "suggestion": null}, {"stepNumber": 2, "stepContent": "kechqurun birga choy ichamiz", "isCorrect": true, "errorDescription": null, "suggestion": null}]'::jsonb, '[{"name": "Imlo", "weightPercent": 35, "score": 80}, {"name": "Grammatika va tinish belgilari", "weightPercent": 35, "score": 78}, {"name": "Mazmun va so''z boyligi", "weightPercent": 30, "score": 85}]'::jsonb, 80.8, 'Yaxshi insho, ba''zi gaplarni kengaytirish mumkin.', 5.0, 'CLEAN', now() - interval '290 hours' + interval '2 minutes'),
  ('ca000000-0000-4000-8000-000000000008', 'c9000000-0000-4000-8000-000000000008', 'I wake up at 7 o''clock. I brush my teeth. My sister go to school with me. We has lunch at 1 pm. I do my homework in the evening.', 0.93, '[{"stepNumber": 1, "stepContent": "My sister go", "isCorrect": false, "errorDescription": "Present Simple: he/she/it bilan fe''lga -s/-es qo''shiladi", "suggestion": "My sister goes"}, {"stepNumber": 2, "stepContent": "We has lunch", "isCorrect": false, "errorDescription": "«we» bilan «have» ishlatiladi", "suggestion": "We have lunch"}]'::jsonb, '[{"name": "Imlo", "weightPercent": 35, "score": 90}, {"name": "Grammatika va tinish belgilari", "weightPercent": 35, "score": 70}, {"name": "Mazmun va so''z boyligi", "weightPercent": 30, "score": 80}]'::jsonb, 80.0, 'Gaplar tushunarli. Uchinchi shaxs birlikdagi -s qo''shimchasi va «have/has» farqiga e''tibor bering.', 4.0, 'CLEAN', now() - interval '20 hours' + interval '2 minutes'),
  ('ca000000-0000-4000-8000-000000000009', 'c9000000-0000-4000-8000-000000000009', 'Every day I get up early. I go to school by bus. My mother cooks breakfast. My father works in a bank. I read books before sleep.', 0.93, '[]'::jsonb, '[{"name": "Imlo", "weightPercent": 35, "score": 96}, {"name": "Grammatika va tinish belgilari", "weightPercent": 35, "score": 95}, {"name": "Mazmun va so''z boyligi", "weightPercent": 30, "score": 90}]'::jsonb, 93.8, 'Barcha gaplar to''g''ri tuzilgan, Present Simple to''g''ri ishlatilgan.', 6.0, 'CLEAN', now() - interval '16 hours' + interval '2 minutes'),
  ('ca000000-0000-4000-8000-000000000010', 'c9000000-0000-4000-8000-000000000010', 'I usually wakes up at 6:30. Then I does exercises. My brother play football every weekend.', 0.93, '[{"stepNumber": 1, "stepContent": "I usually wakes", "isCorrect": false, "errorDescription": "«I» bilan fe''lga -s qo''shilmaydi", "suggestion": "I usually wake"}, {"stepNumber": 2, "stepContent": "I does", "isCorrect": false, "errorDescription": "«I» bilan «do» ishlatiladi", "suggestion": "I do"}, {"stepNumber": 3, "stepContent": "My brother play", "isCorrect": false, "errorDescription": "he/she/it bilan -s kerak", "suggestion": "My brother plays"}]'::jsonb, '[{"name": "Imlo", "weightPercent": 35, "score": 88}, {"name": "Grammatika va tinish belgilari", "weightPercent": 35, "score": 55}, {"name": "Mazmun va so''z boyligi", "weightPercent": 30, "score": 60}]'::jsonb, 68.0, 'Faqat uchta gap yozilgan, topshiriqda 10 ta gap so''ralgan. Fe''l shakllarini takrorlang.', 3.0, 'CLEAN', now() - interval '12 hours' + interval '2 minutes'),
  ('ca000000-0000-4000-8000-000000000011', 'c9000000-0000-4000-8000-000000000011', 'Every day I get up early. I go to school by bus. My mother cooks breakfast. My father works in a bank. I read books before sleep.', 0.93, '[]'::jsonb, '[{"name": "Imlo", "weightPercent": 35, "score": 96}, {"name": "Grammatika va tinish belgilari", "weightPercent": 35, "score": 95}, {"name": "Mazmun va so''z boyligi", "weightPercent": 30, "score": 85}]'::jsonb, 92.3, 'Matn deyarli so''zma-so''z boshqa o''quvchi ishiga mos keladi.', 88.0, 'SUSPICIOUS', now() - interval '10 hours' + interval '2 minutes'),
  ('ca000000-0000-4000-8000-000000000012', 'c9000000-0000-4000-8000-000000000012', 'Amir Temur 1370-yilda hokimiyatga keldi. Davlat poytaxti Samarqand edi. U qurilishga katta e''tibor berdi, Samarqandda Bibixonim masjidi qurildi. Temur tuzuklari davlat qonunlari to''plami edi.', 0.93, '[{"stepNumber": 1, "stepContent": "1370-yilda hokimiyatga keldi", "isCorrect": true, "errorDescription": null, "suggestion": null}, {"stepNumber": 2, "stepContent": "Poytaxti Samarqand edi", "isCorrect": true, "errorDescription": null, "suggestion": null}, {"stepNumber": 3, "stepContent": "Bibixonim masjidi qurildi", "isCorrect": true, "errorDescription": null, "suggestion": null}, {"stepNumber": 4, "stepContent": "Temur tuzuklari davlat qonunlari to''plami", "isCorrect": true, "errorDescription": null, "suggestion": null}]'::jsonb, '[{"name": "Faktlar aniqligi", "weightPercent": 40, "score": 95}, {"name": "Savolga to''liq javob", "weightPercent": 30, "score": 90}, {"name": "Fikr izchilligi va dalillar", "weightPercent": 30, "score": 88}]'::jsonb, 91.4, 'Javob to''liq va faktlar to''g''ri. Islohotlarni yana bir-ikki misol bilan boyitish mumkin.', 5.0, 'CLEAN', now() - interval '40 hours' + interval '2 minutes'),
  ('ca000000-0000-4000-8000-000000000013', 'c9000000-0000-4000-8000-000000000013', 'Amir Temur davlati 1370-yil tuzilgan. Poytaxti Buxoro edi. U ko''p jang qildi.', 0.93, '[{"stepNumber": 1, "stepContent": "1370-yil tuzilgan", "isCorrect": true, "errorDescription": null, "suggestion": null}, {"stepNumber": 2, "stepContent": "Poytaxti Buxoro edi", "isCorrect": false, "errorDescription": "Fakt xatosi: Temur davlatining poytaxti Samarqand edi", "suggestion": "Poytaxti Samarqand edi"}, {"stepNumber": 3, "stepContent": "U ko''p jang qildi", "isCorrect": false, "errorDescription": "Savolga to''liq javob emas: islohotlar haqida so''ralgan", "suggestion": "Qurilish, savdo yoki «Temur tuzuklari» haqida yozing"}]'::jsonb, '[{"name": "Faktlar aniqligi", "weightPercent": 40, "score": 55}, {"name": "Savolga to''liq javob", "weightPercent": 30, "score": 50}, {"name": "Fikr izchilligi va dalillar", "weightPercent": 30, "score": 60}]'::jsonb, 55.0, 'Bitta fakt xatosi bor va islohotlar haqida javob berilmagan.', 4.0, 'CLEAN', now() - interval '36 hours' + interval '2 minutes'),
  ('ca000000-0000-4000-8000-000000000014', 'c9000000-0000-4000-8000-000000000014', 'Sohibqiron Amir Temur 1370-yilda Balxda qurultoyda oliy hukmdor etib saylandi. Uning davlati poytaxti Samarqand bo''lib, u yerda Ko''ksaroy qasri, Bibixonim jome masjidi bunyod etildi. «Temur tuzuklari»da davlatni boshqarish qoidalari bayon qilingan.', 0.93, '[{"stepNumber": 1, "stepContent": "1370-yilda Balxda saylandi", "isCorrect": true, "errorDescription": null, "suggestion": null}, {"stepNumber": 2, "stepContent": "Poytaxti Samarqand", "isCorrect": true, "errorDescription": null, "suggestion": null}, {"stepNumber": 3, "stepContent": "Ko''ksaroy va Bibixonim bunyod etildi", "isCorrect": true, "errorDescription": null, "suggestion": null}]'::jsonb, '[{"name": "Faktlar aniqligi", "weightPercent": 40, "score": 96}, {"name": "Savolga to''liq javob", "weightPercent": 30, "score": 92}, {"name": "Fikr izchilligi va dalillar", "weightPercent": 30, "score": 94}]'::jsonb, 94.2, 'A''lo javob: aniq faktlar va dalillar bilan.', 9.0, 'CLEAN', now() - interval '30 hours' + interval '2 minutes')
