-- Ona tili, ingliz tili va tarix: the three checking modes on real-looking work.
-- Adds three subject teachers, their classes, assignments and AI-checked submissions
-- (some flagged, one waiting for manual grading) next to the maths/physics data in
-- demo-seed.sql. Idempotent (ON CONFLICT DO NOTHING); the new teachers reuse the
-- maths teacher's password hash, so they share whatever password the school uses.
BEGIN;

ON CONFLICT DO NOTHING;

SELECT t.id, t.first_name, t.last_name, t.phone, g.password_hash, 'TEACHER', true, 'cc021f70-256f-45c0-be19-ab7beddab1b3'::uuid, now() - interval '70 days'
FROM (VALUES
  ('c6000000-0000-4000-8000-000000000001'::uuid, 'Feruza', 'Rahmonova', '+998915207341'),
  ('c6000000-0000-4000-8000-000000000002'::uuid, 'Kamola', 'Tursunova', '+998916738420'),
  ('c6000000-0000-4000-8000-000000000003'::uuid, 'Rustam', 'Aliyev', '+998917462053')
) AS t(id, first_name, last_name, phone) CROSS JOIN (SELECT password_hash FROM users WHERE id = '7c0adf23-9276-431a-bd18-5b4873eab945') g
ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;

COMMIT;
